draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 30 * Math.sin(t), H/2, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 30 * Math.sin(t + Math.PI), H/2, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 30 * Math.sin(t), 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 30 * Math.sin(t + Math.PI), 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('1', W/2 + 20 * Math.sin(t), H/2 - 10);
  ctx.fillText('1', W/2 + 20 * Math.sin(t + Math.PI), H/2 - 10);
  ctx.fillText('9', W/2 - 10, H/2 + 20 * Math.sin(t));
  ctx.fillText('0', W/2 - 10, H/2 + 20 * Math.sin(t + Math.PI));
  ctx.restore();
}
